head.b:skin:
:root{--cream:#F6F1E8;--paper:#FFFDF8;--ink:#24221F;--muted:#746D63;--terra:#C95746;--sage:#A6B29F;--blue:#8EA5B8;--yellow:#E2B45A;--line:#DDD5C8;--shadow:0 10px 28px rgba(36,34,31,.07);--radius:18px}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--cream);color:var(--ink);font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.65}a{color:inherit;text-decoration:none}img{display:block;max-width:100%;height:auto}.wrap{width:min(1180px,92vw);margin:0 auto}
.topline{border-top:3px solid var(--ink);border-bottom:1px solid var(--line);padding:9px 0;color:var(--muted);font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase}
.masthead{padding:30px 0 24px;display:flex;align-items:flex-end;justify-content:space-between;gap:24px}.brand{display:block;font-size:42px;font-weight:900;letter-spacing:-.055em;line-height:.96}.brand-sub{margin-top:9px;color:var(--muted);font-size:11px;font-weight:700;letter-spacing:.18em;text-transform:uppercase}.search-link{display:inline-flex;align-items:center;gap:8px;border:1px solid #CEC5B8;background:var(--paper);border-radius:999px;padding:11px 17px;font-size:13px;font-weight:700}
.nav-area{border-top:1px solid var(--line);border-bottom:1px solid var(--line);background:rgba(255,253,248,.62);padding:14px 0}.nav-grid{display:flex;flex-wrap:wrap;gap:9px}.nav-pill{display:inline-flex;align-items:center;gap:8px;min-height:36px;padding:8px 12px;border:1px solid #D5CDC1;border-radius:999px;background:var(--paper);font-size:13px;font-weight:600;line-height:1.1;white-space:nowrap;transition:all .16s ease}.nav-pill:hover{border-color:var(--terra);transform:translateY(-1px);box-shadow:0 5px 15px rgba(36,34,31,.06)}.nav-icon{width:23px;height:23px;flex:0 0 23px;display:inline-grid;place-items:center;border-radius:50%;background:#EEE7DC;font-size:13px}
.hero{padding:34px 0 20px;display:grid;grid-template-columns:minmax(0,1.55fr) minmax(300px,.65fr);gap:22px}.hero-main{min-height:500px;position:relative;overflow:hidden;border-radius:var(--radius);background:#D9D1C5}.hero-main img{width:100%;height:100%;object-fit:cover}.hero-overlay{position:absolute;left:0;right:0;bottom:0;padding:52px 44px 38px;color:#fff;background:linear-gradient(to top,rgba(0,0,0,.8),rgba(0,0,0,0))}.eyebrow{font-size:11px;font-weight:800;letter-spacing:.2em;text-transform:uppercase}.hero-overlay h1{max-width:760px;margin:8px 0 12px;font-family:Georgia,"Times New Roman",serif;font-size:clamp(44px,5.7vw,78px);font-weight:700;line-height:.94;letter-spacing:-.045em}.hero-overlay p{max-width:690px;margin:0;font-size:18px}.hero-side{display:grid;gap:22px}.side-card{min-height:239px;display:flex;flex-direction:column;justify-content:flex-end;padding:28px;border-radius:var(--radius);background:var(--paper);box-shadow:var(--shadow)}.side-label{width:max-content;padding:6px 10px;border-radius:999px;background:var(--sage);color:var(--ink);font-size:10px;font-weight:800;letter-spacing:.13em;text-transform:uppercase}.side-label.blue{background:var(--blue)}.side-card h2{margin:12px 0 8px;font-family:Georgia,"Times New Roman",serif;font-size:31px;line-height:1.03;letter-spacing:-.03em}.side-card p{margin:0;color:var(--muted);font-size:14px}
.section{padding:30px 0}.section-head{margin-bottom:17px;display:flex;align-items:flex-end;justify-content:space-between;gap:20px}.section-head h2{margin:0;font-family:Georgia,"Times New Roman",serif;font-size:38px;line-height:1.02;letter-spacing:-.04em}.section-head a{color:var(--terra);font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}
.topic-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.topic-card{min-height:150px;padding:20px;display:flex;flex-direction:column;justify-content:space-between;border:1px solid #E0D8CB;border-radius:16px;background:var(--paper);transition:all .16s ease}.topic-card:hover{border-color:var(--terra);transform:translateY(-2px);box-shadow:var(--shadow)}.topic-num{color:var(--muted);font-size:10px;font-weight:800;letter-spacing:.14em}.topic-name{font-family:Georgia,"Times New Roman",serif;font-size:23px;line-height:1.05}
.feature-band{margin:20px 0 10px;padding:34px 36px;display:flex;align-items:center;justify-content:space-between;gap:28px;border-radius:var(--radius);background:var(--ink);color:#fff}.feature-band h2{margin:0 0 9px;font-family:Georgia,"Times New Roman",serif;font-size:36px;line-height:1.04}.feature-band p{margin:0;color:#D4D0C8}.feature-band a{flex:0 0 auto;padding:12px 18px;border-radius:999px;background:#fff;color:var(--ink);font-size:12px;font-weight:800;letter-spacing:.1em;text-transform:uppercase}
.content{padding:50px 0;display:grid;grid-template-columns:minmax(0,1fr) 285px;gap:38px}.sidebar{height:max-content}.sidebox{padding:21px;margin-bottom:16px;border:1px solid #E0D8CB;border-radius:16px;background:var(--paper)}.sidebox h3{margin:0 0 12px;font-size:12px;font-weight:800;letter-spacing:.13em;text-transform:uppercase}.sidebox p{margin:0;color:var(--muted);font-size:14px}.sidebox ul{list-style:none;padding:0;margin:0}.sidebox li{padding:8px 0;border-bottom:1px solid var(--line);font-size:14px}
#Blog1,#Blog2{width:100%}.post-outer{margin-bottom:40px}.post-title,.entry-title,.post-title a{font-family:Georgia,"Times New Roman",serif!important;color:var(--ink)!important;line-height:1.04!important;letter-spacing:-.04em!important}.post-title{font-size:48px!important}.post-body{color:#39352F!important;font-size:18px!important;line-height:1.82!important}.post-body h2,.post-body h3{font-family:Georgia,"Times New Roman",serif!important;line-height:1.12!important}.post-body h2{font-size:35px!important}.post-body h3{font-size:27px!important}.post-body img{border-radius:14px}
.footer{margin-top:60px;background:#1D1C19;color:#F5F1E9;padding:52px 0}.footer-grid{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:38px}.footer h3{margin:0 0 10px;font-family:Georgia,"Times New Roman",serif;font-size:34px;line-height:1}.footer p,.footer a{color:#BDB8AF;font-size:14px}.footer-links{display:grid;gap:7px}.copyright{margin-top:34px;padding-top:18px;border-top:1px solid #35332F;color:#8F8A82;font-size:11px}
@media(max-width:980px){.hero{grid-template-columns:1fr}.hero-main{min-height:440px}.topic-grid{grid-template-columns:repeat(2,1fr)}.content{grid-template-columns:1fr}.footer-grid{grid-template-columns:1fr 1fr}}
@media(max-width:640px){body{font-size:15px}.topline{font-size:9px}.masthead{padding:22px 0 18px}.brand{font-size:31px}.brand-sub{font-size:9px;letter-spacing:.13em}.search-link{display:none}.nav-grid{gap:7px}.nav-pill{font-size:12px;padding:8px 10px;min-height:34px}.nav-icon{width:21px;height:21px;flex-basis:21px}.hero{padding-top:22px}.hero-main{min-height:390px}.hero-overlay{padding:30px 24px 26px}.hero-overlay h1{font-size:43px}.hero-overlay p{font-size:15px}.side-card{min-height:210px}.side-card h2{font-size:27px}.topic-grid{grid-template-columns:1fr 1fr}.section-head h2{font-size:31px}.feature-band{display:block;padding:28px}.feature-band h2{font-size:31px}.feature-band a{display:inline-block;margin-top:18px}.footer-grid{grid-template-columns:1fr}.content{padding:35px 0}.post-title{font-size:42px!important}.post-body{font-size:17px!important}}
